{
  if (!navigator.gpu) throw new Error("WebGPU is not supported in this browser.");

  // 1. Canvas (640x360 buffer, scaled to fill the column)
  const canvas = DOM.canvas(640, 360);
  canvas.style.width = "100%";
  canvas.style.height = "auto";

  // 2. Adapter and device
  const adapter = await navigator.gpu.requestAdapter();
  const device = await adapter.requestDevice();

  // 3. Context
  const context = canvas.getContext("webgpu");
  const format = navigator.gpu.getPreferredCanvasFormat();
  context.configure({ device, format });
  // Not part of the lesson: lets this canvas be recorded by opening the page with ?record
  (await import(new URL("../lib/gpu.js", document.baseURI).href)).enableRecording(canvas);

  // 4. Record: a render pass that clears to the site's dark background (#1a1a1a)
  const encoder = device.createCommandEncoder();
  const pass = encoder.beginRenderPass({
    colorAttachments: [
      {
        view: context.getCurrentTexture().createView(),
        clearValue: { r: 0.102, g: 0.102, b: 0.102, a: 1.0 }, // #1a1a1a
        loadOp: "clear",
        storeOp: "store",
      },
    ],
  });
  pass.end();

  // 5. Submit
  device.queue.submit([encoder.finish()]);

  yield canvas;
}








