    code: `
      @group(0) @binding(0) var&lt;storage, read&gt; data: array&lt;vec2f&gt;;
      @group(0) @binding(1) var&lt;storage, read_write&gt; peak: array&lt;atomic&lt;u32&gt;, 1&gt;;

      @compute @workgroup_size(16, 16)
      fn findPeak(@builtin(global_invocation_id) id: vec3u) {
        if (id.x &gt;= ${N}u || id.y &gt;= ${N}u) { return; }
        let v = data[id.y * ${N}u + id.x];
